package main

import "fmt"

func main() {
	s := []int{10, 20, 30}
	t := s          // copies the header (ptr, len, cap), not the data
	t[0] = 99       // writes through the SHARED backing array
	fmt.Println(s)  // s sees the change too
	fmt.Println(len(s), cap(s))
	// Output: [99 20 30]
	// 3 3
}

package main

import "fmt"

func main() {
	s := make([]int, 2, 10) // len 2, cap 10
	fmt.Println(len(s), cap(s))
	s = s[:5]               // re-slice up to cap without allocating
	fmt.Println(len(s), cap(s))
	// Output: 2 10
	// 5 10
}

package main

import "fmt"

func main() {
	s := make([]int, 0, 2)
	for i := 1; i <= 3; i++ {
		s = append(s, i) // assign the result back!
		fmt.Println(len(s), cap(s))
	}
	// Output: 1 2
	// 2 2
	// 3 4
}

