func main() {
	a := []int{1, 2, 3, 4}
	b := a[1:3]     // shares a's backing array
	b[0] = 99       // writes a[1] too
	fmt.Println(a)
	fmt.Println(b)
	// Output: [1 99 3 4]
	// [99 3]
}

