	var s []int // nil slice: len 0, cap 0, no backing array
	fmt.Println(s == nil, len(s), cap(s))
	s = append(s, 1) // appending to nil is fine
	fmt.Println(s == nil, s)
	// Output: true 0 0
	// false [1]
}

package main

import "fmt"

func main() {
	a := []int{1, 2, 3}
	b := make([]int, len(a)) // independent backing array
	n := copy(b, a)          // copy elements, not the header
	b[0] = 99                // does NOT touch a
	fmt.Println(n, a, b)
	// Output: 3 [1 2 3] [99 2 3]
}

