package solution

import (
	"reflect"
	"testing"
)

func TestSolve(t *testing.T) {
	cases := []struct {
		in, want []int
	}{
		{[]int{1, 2, 2, 3, 1}, []int{1, 2, 3}},
		{[]int{}, []int{}},
		{[]int{5, 5, 5}, []int{5}},
	}
	for _, c := range cases {
		if got := Solve(c.in); !reflect.DeepEqual(got, c.want) {
			t.Errorf("Solve(%v)=%v want %v", c.in, got, c.want)
		}
	}
}

