func Reverse(s []int) {
	for i, j := 0, len(s)-1; i < j; i, j = i+1, j-1 {
		s[i], s[j] = s[j], s[i] // swap ends, move inward
	}
}

func RemoveAt(s []int, i int) []int {
	if i < 0 || i >= len(s) { // guard against out-of-range indices
		return s
	}
	// copy the tail (elements after i) left onto the removed slot
	return append(s[:i], s[i+1:]...)
}
